const RECIPE_GROUPS = [{"id":"espresso_pure","icon":"coffee","title":"خانواده اسپرسو","items":[{"id":24,"title":"اسپرسو نرمال (Espresso Normale)","body":"<ul><li>گام ۱ (آماده‌سازی دستگاه): دستگاه را روشن کرده و تا دمای پایدار ۹۲-۹۳ درجه سانتی‌گراد (گروه) برسانید. پورتافیلتر را در گروه قرار دهید تا گرم شود.</li><li>گام ۲ (توزین و آسیاب): دقیقاً ۱۸ گرم دانه قهوه برشته شده (درجه متوسط) را با آسیاب به درجه ریز (مشابه نمک خوراکی، حدود ۲۵۰-۳۰۰ میکرون) آسیاب کنید.</li><li>گام ۳ (پخش و تَمپ): پودر را در سبد ۱۸ گرمی پورتافیلتر بریزید، به آرامی سطح را با انگشت صاف کنید. تمپر را با فشار ثابت ۱۲-۱۵ کیلوگرم به‌صورت مستقیم و چرخشی (۴۵ درجه) بر روی سطح پودر فشار دهید تا یک قرص یکدست تشکیل شود.</li><li>گام ۴ (قفل و استارت): پورتافیلتر را در گروه دستگاه قفل کنید. فنجان گرم‌شده (۹۰-۹۵ میلی‌لیتری) را زیر نازل قرار دهید. بلافاصله کرونومتر را شروع کنید و دکمه عصاره‌گیری را بزنید.</li><li>گام ۵ (عصاره‌گیری): وزن خروجی را تا رسیدن به ۳۶ گرم (نسبت ۱:۲) کنترل کنید. زمان ایده‌آل: ۲۵ تا ۳۰ ثانیه (اگر زودتر به ۳۶ گرم رسید، آسیاب را ریزتر کنید و بالعکس).</li><li>گام ۶ (سرو): جریان عصاره ابتدا قطره‌قطره، سپس به صورت یک روبان یکنواخت قهوه‌ای با کرمای فندقی ضخیم خارج می‌شود. پس از پایان، هم بزنید و بلافاصله سرو کنید.</li></ul>","kind":"item"},{"id":25,"title":"ریسترتو (Ristretto)","body":"<ul><li>دقیقاً مراحل ۱ تا ۴ اسپرسو را انجام دهید.</li><li>تغییر در گام ۵: عصاره‌گیری را تا خروجی ۱۸ تا ۲۰ گرم (نسبت ۱:۱) محدود کنید. زمان عصاره‌گیری: ۱۵ تا ۲۰ ثانیه (آسیاب را کمی ریزتر از اسپرسو نرمال کنید تا زمان به این بازه برسد).</li><li>سرو: حجم بسیار کم، غلیظ‌ترین، شیرین‌ترین و کم‌تلخ‌ترین مدل اسپرسویی.</li></ul>","kind":"item"},{"id":26,"title":"دوپیو (Doppio)","body":"<ul><li>دقیقاً مراحل ۱ تا ۴ را انجام دهید، اما با ۲۰ تا ۲۲ گرم پودر قهوه در سبد دبل (دقیقاً همانند اسپرسو، فقط دوز دوبرابر).</li><li>گام ۵: عصاره‌گیری تا خروجی ۴۰ تا ۴۴ گرم (نسبت ۱:۲) در زمان ۲۵ تا ۳۰ ثانیه.</li><li>سرو: همان اسپرسو با حجم دوبرابر.</li></ul>","kind":"item"},{"id":27,"title":"لونگو (Lungo)","body":"<ul><li>مراحل ۱ تا ۴ را انجام دهید (۱۸ گرم پودر، اما با زاویه‌ای که آب بیشتری از بستر عبور کند).</li><li>تغییر: آسیاب را کمی درشت‌تر از اسپرسو نرمال کنید (حدود ۳۵۰ میکرون).</li><li>گام ۵: عصاره‌گیری تا خروجی ۵۴ تا ۶۰ گرم (نسبت ۱:۳) در زمان ۳۵ تا ۴۰ ثانیه. (مراقب تلخی بیش‌ازحد باشید).</li><li>سرو: حجم بزرگ‌تر، کمی تلخ‌تر و با بدنه‌ای سبک‌تر.</li></ul>","kind":"item"},{"id":28,"title":"کافه کرما (Caffè Crema)","body":"<ul><li>این مدل، لونگوی بسیار کشیده است.</li><li>گام ۱: ۱۸ گرم پودر، آسیاب درشت‌تر از لونگو (حدود ۴۰۰ میکرون).</li><li>گام ۲: آب را روی ۹۰-۹۱ درجه تنظیم کنید تا از تلخی شدید جلوگیری شود.</li><li>گام ۳: عصاره‌گیری تا خروجی ۱۰۰ تا ۱۲۰ میلی‌لیتر (نسبت ۱:۶ تا ۱:۷) در زمان ۵۰ تا ۶۰ ثانیه.</li><li>سرو: لایه کرم ضخیم و ماندگار، طعمی ملایم‌تر و قابل‌نوشیدن مانند قهوه فیلتری غلیظ. این نوشیدنی در فنجان‌های بزرگ (۱۸۰ میلی‌لیتری) سرو می‌شود.</li></ul>","kind":"item"}],"hero":"assets/images/espresso_pure.svg"},{"id":"espresso_diluted","icon":"droplet","title":"اسپرسو رقیق‌شده","items":[{"id":32,"title":"آمریکانو (Americano)","body":"<ul><li>گام ۱ (آماده‌سازی فنجان): یک فنجان بزرگ (۲۰۰–۲۵۰ میلی‌لیتری) را انتخاب کرده و آن را با آب داغ (۹۰ درجه) گرم کنید تا دمای نوشیدنی حفظ شود. سپس آب را خالی کنید.</li><li>گام ۲ (ریختن آب داغ): ابتدا بین ۱۲۰ تا ۱۵۰ میلی‌لیتر آب داغ (۹۲–۹۳ درجه سانتی‌گراد) را در فنجان بریزید. (نسبت نهایی آب به اسپرسو حدود ۲:۱ یا ۳:۱ است).</li><li>گام ۳ (افزودن اسپرسو): یک شات اسپرسوی تازه دم (۳۶ گرم) را به‌آرامی و مستقیم روی سطح آب داغ بریزید. (اگر سریع بریزید، لایه کِرِما از بین می‌رود؛ بهتر است پشت قاشق بریزید تا کِرِما روی سطح باقی بماند).</li><li>گام ۴ (سرو): بدون هم زدن (مشتری خود هم می‌زند) سرو کنید تا لایه طلایی کِرِما روی سطح کاملاً مشخص باشد. طعمی ملایم و شبیه قهوه سیاه دم‌آوری اما با بدنه اسپرسو.</li></ul>","kind":"item"},{"id":33,"title":"لانگ بلک (Long Black)","body":"<ul><li>(نکته کلیدی: برعکس آمریکانو عمل میشود تا کِرِما کاملاً حفظ شود)</li><li>گام ۱ (آماده‌سازی فنجان): یک فنجان بزرگ (۲۰۰–۲۲۰ میلی‌لیتری) را با آب داغ گرم کنید و خالی کنید.</li><li>گام ۲ (ریختن آب داغ): بین ۱۰۰ تا ۱۲۰ میلی‌لیتر آب داغ (۹۰–۹۲ درجه) را در فنجان بریزید. حجم آب در لانگ بلک کمی کمتر از آمریکانو است (۱.۵ تا ۲ برابر اسپرسو).</li><li>گام ۳ (افزودن اسپرسو – معکوس): یک شات اسپرسوی تازه دم (۳۶ گرم) را با دقت و به‌آرامی، درست از وسط، بر روی سطح آب بریزید. از قاشق استفاده کنید تا جریان اسپرسو به‌آرامی روی آب بنشیند.</li><li>گام ۴ (نتیجه): لایه کِرِما به‌صورت یکپارچه و ضخیم روی سطح شناور می‌ماند (چون اسپرسو آخرین لایه است). طعمی غلیظ‌تر و با بدنه‌تر از آمریکانو.</li></ul>","kind":"item"},{"id":34,"title":"آیس آمریکانو (Iced Americano)","body":"<ul><li>گام ۱ (آماده‌سازی لیوان): یک لیوان بلند (۳۵۰–۴۰۰ میلی‌لیتری) را تا نیمه از یخ درشت (کیوب) پر کنید. از یخ ریز استفاده نکنید تا زود آب نشود.</li><li>گام ۲ (ریختن آب سرد): بین ۱۰۰ تا ۱۲۰ میلی‌لیتر آب سرد (ترجیحاً تصفیه‌شده و سرد) را روی یخ‌ها بریزید تا سطح آب به حدود ۱/۳ لیوان برسد.</li><li>گام ۳ (افزودن اسپرسو): یک شات اسپرسوی ۳۶ گرمی را مستقیماً و داغ روی یخ‌ها و آب بریزید. (برخورد اسپرسوی داغ با یخ، باعث شکستن و آزادسازی عطر‌ها می‌شود).</li><li>گام ۴ (مخلوط‌کردن مختصر): با یک قاشق بلند، ۳ تا ۴ بار به‌آرامی هم بزنید تا یکدست شود.</li><li>گام ۵ (سرو فوری): بلافاصله سرو کنید تا یخ کاملاً آب نشده و نوشیدنی قدرت خود را حفظ کند. (در صورت تمایل، یک برش لیمو یا پرتقال به لبه لیوان اضافه کنید).</li></ul>","kind":"item"}],"hero":"assets/images/espresso_diluted.svg"},{"id":"espresso_milk","icon":"milk","title":"اسپرسو و شیر","items":[{"id":38,"title":"کاپوچینو (Cappuccino)","body":"<ul><li>گام ۱ (دم‌آوری اسپرسو): یک شات اسپرسوی ۳۶ گرمی در فنجان ۱۵۰–۱۸۰ میلی‌لیتری آماده کنید.</li><li>گام ۲ (بافت‌دهی شیر): ۱۲۰ میلی‌لیتر شیر سرد (۴ درجه) را در پیتچر بریزید. نازل بخار را ۱ سانتی‌متر زیر سطح شیر قرار دهید و بخار را باز کنید. با ایجاد گرداب (تصور کنید شیر را در حال چرخش) تا دمای ۵۵–۶۰ درجه سانتی‌گراد برسانید. حجم شیر باید ۳۰٪ افزایش یابد و کفی با حباب‌های میکروسکوپی و براق ایجاد شود (میکروفوم).</li><li>گام ۳ (ترکیب): شیر را حدود ۱۰ ثانیه بگذارید تا کف و شیر کمی جدا شود. ابتدا شیر مایع را داخل اسپرسو بریزید، سپس با قاشق، کف غلیظ را روی سطح قرار دهید تا یک لایه یکنواخت (حدود ۱ سانتی‌متر) تشکیل شود. نسبت نهایی: ۱/۳ اسپرسو، ۱/۳ شیر، ۱/۳ کف.</li><li>گام ۴ (سرو): بلافاصله سرو کنید، کف باید حالتی ابری و مجزا داشته باشد.</li></ul>","kind":"item"},{"id":39,"title":"کافه لاته (Caffè Latte)","body":"<ul><li>گام ۱: یک شات اسپرسوی ۳۶ گرمی در لیوان بلند (۲۲۰–۲۵۰ میلی‌لیتری) بریزید.</li><li>گام ۲ (بافت‌دهی شیر): ۱۸۰ میلی‌لیتر شیر را بافت‌دهی کنید (دمای ۵۵–۶۰ درجه) اما با کف کمتر (فقط لایه نازک ۳ میلی‌متری روی سطح). شیر باید حالت مایع براق با مقدار کمی کف ریز داشته باشد.</li><li>گام ۳ (ترکیب): شیر را به‌آرامی و با زاویه ۴۵ درجه از دیواره لیوان بریزید تا با اسپرسو مخلوط شود و لایه نازکی از کف روی سطح بنشیند.</li><li>گام ۴: نسبت نهایی: ۱ شات اسپرسو به ۳-۴ قسمت شیر. سرو در لیوان بلند (بدون کف مجزا).</li></ul>","kind":"item"},{"id":40,"title":"فلت وایت (Flat White)","body":"<ul><li>گام ۱: یک دبل شات ریسترتو (۳۰–۳۵ گرم، عصاره‌گیری ۱۸ ثانیه‌ای) یا دبل اسپرسو (۴۰–۴۴ گرم) را در فنجان کوچک ۱۵۰ میلی‌لیتری بریزید.</li><li>گام ۲ (میکروفوم خامه‌ای): ۱۴۰ میلی‌لیتر شیر را با بافت‌دهی بسیار دقیق به کفی صاف و براق (میکروفوم مایع، بدون حباب درشت) تا دمای ۵۵ درجه برسانید. کف باید حدود ۲-۳ میلی‌متر ضخامت داشته باشد.</li><li>گام ۳ (ریختن): شیر را از ارتفاع کم (نزدیک به سطح) به‌آرامی داخل فنجان بریزید تا یک لایه یکنواخت و براق روی قهوه تشکیل شود (بدون تفکیک لایه‌ها). با یک حرکت نهایی، یک دایره سفید کوچک روی سطح بکشید.</li><li>سرو: طعمی غلیظ‌تر از لاته با بافتی کرم‌مانند.</li></ul>","kind":"item"},{"id":41,"title":"اسپرسو ماکیاتو (Espresso Macchiato)","body":"<ul><li>گام ۱: یک شات اسپرسوی ۳۶ گرمی را در فنجان کوچک اسپرسو (۹۰ میلی‌لیتری) بریزید.</li><li>گام ۲ (افزودن کف): با یک قاشق کوچک، یک قاشق غذاخوری (حدود ۱۵ میلی‌لیتر) از کف خشک شیر (بدون شیر مایع) را روی مرکز اسپرسو قرار دهید.</li><li>گام ۳: لکه سفید کف روی سطح قهوه نمایان است. نیازی به هم زدن نیست. سرو کنید.</li></ul>","kind":"item"},{"id":42,"title":"لاته ماکیاتو (Latte Macchiato)","body":"<ul><li>گام ۱ (برعکس): یک لیوان بلند (۲۵۰ میلی‌لیتری) بردارید. ۱۸۰ میلی‌لیتر شیر را بافت‌دهی کنید (میکروفوم با کف ۱ سانتی‌متری) و در لیوان بریزید.</li><li>گام ۲ (افزودن اسپرسو): یک شات اسپرسوی ۳۶ گرمی را به‌آرامی از وسط روی شیر بریزید (بهترین کار ریختن پشت قاشق است تا لایه‌ها جدا بمانند).</li><li>گام ۳: نتیجه: سه لایه قابل‌تشخیص – شیر سفید در پایین، اسپرسو در وسط، کف در بالا. با قاشق هم نزنید.</li></ul>","kind":"item"},{"id":43,"title":"موکا (Mocha)","body":"<ul><li>گام ۱ (پایه شکلات): در فنجان ۱۸۰–۲۰۰ میلی‌لیتری، ۲ قاشق غذاخوری پودر کاکائوی مرغوب یا ۳۰ گرم شکلات تلخ ذوب‌شده را با ۳۰ میلی‌لیتر شیر داغ مخلوط کنید تا خمیر یکدست شود.</li><li>گام ۲: یک شات اسپرسوی ۳۶ گرمی را روی خمیر شکلات بریزید و هم بزنید.</li><li>گام ۳ (شیر بخارزده): ۱۲۰ میلی‌لیتر شیر را با کف متوسط بافت‌دهی کنید و درون فنجان بریزید.</li><li>گام ۴: روی آن با خامه فرم‌گرفته تزیین کرده و پودر کاکائو بپاشید.</li></ul>","kind":"item"},{"id":44,"title":"کورتادو (Cortado)","body":"<ul><li>گام ۱: یک شات اسپرسوی ۳۶ گرمی در فنجان ۱۰۰ میلی‌لیتری.</li><li>گام ۲ (شیر بدون کف): ۳۶ میلی‌لیتر شیر را فقط گرم کنید (بدون بافت‌دهی، بدون کف) تا ۶۰ درجه (فقط بخار بدهید بدون مکش هوا).</li><li>گام ۳: شیر گرم را به‌صورت یک‌دست داخل اسپرسو بریزید. نسبت ۱:۱، بدون کف. هم بزنید و سرو کنید.</li></ul>","kind":"item"},{"id":45,"title":"پیکولو لاته (Piccolo Latte)","body":"<ul><li>گام ۱: یک شات ریسترتو (۲۰ گرم، نسبت ۱:۱) در فنجان ۸۰–۹۰ میلی‌لیتری.</li><li>گام ۲: ۶۰ میلی‌لیتر شیر را با میکروفوم غلیظ (کف کم، براق) بافت‌دهی کنید.</li><li>گام ۳: شیر را روی ریسترتو بریزید (نسبت ۱:۳ شیر به قهوه). نتیجه: یک لاته کوچک با طعم بسیار غلیظ.</li></ul>","kind":"item"},{"id":46,"title":"جبل‌الطارق (Gibraltar)","body":"<ul><li>دقیقاً مانند کورتادو، اما در لیوان شیشه‌ای ضخیم ۹۰ میلی‌لیتری (لیوان Gibraltar با کف گرد) سرو می‌شود. نسبت ۱:۱ اسپرسو و شیر گرم بدون کف.</li></ul>","kind":"item"},{"id":47,"title":"ماروکینو (Marocchino)","body":"<ul><li>گام ۱: کف لیوان شیشه‌ای (۱۰۰ میلی‌لیتری) را با پودر کاکائو بپوشانید.</li><li>گام ۲: یک شات اسپرسوی ۳۶ گرمی بریزید.</li><li>گام ۳: یک قاشق غذاخوری کف شیر (خشک) روی آن قرار دهید و پودر کاکائو بپاشید. (بدون شیر مایع).</li></ul>","kind":"item"},{"id":48,"title":"اسپرسو کن پانا (Espresso con Panna)","body":"<ul><li>گام ۱: یک شات اسپرسوی ۳۶ گرمی در فنجان اسپرسو.</li><li>گام ۲: یک لایه ضخیم (حدود ۳۰ میلی‌لیتر) خامه فرم‌گرفته با شیرینی کم را روی اسپرسو تزریق کنید.</li><li>گام ۳: بلافاصله سرو (خامه و اسپرسو لایه‌های جدا دارند).</li></ul>","kind":"item"},{"id":49,"title":"کافه بروه (Caffè Breve)","body":"<ul><li>گام ۱: یک شات اسپرسوی ۳۶ گرمی در فنجان ۱۵۰ میلی‌لیتری.</li><li>گام ۲: ۹۰ میلی‌لیتر شیر نیم‌نیم (Half &amp; Half – مخلوط شیر و خامه) را بافت‌دهی کنید تا کفی سنگین و کرم‌مانند (۵۵ درجه).</li><li>گام ۳: شیر سنگین را داخل اسپرسو بریزید. طعمی بسیار چرب‌تر و غنی‌تر از لاته.</li></ul>","kind":"item"}],"hero":"assets/images/espresso_milk.svg"},{"id":"espresso_extra","icon":"sparkle","title":"اسپرسو و افزودنی‌های خاص","items":[{"id":54,"title":"آفوگاتو (Affogato)","body":"<ul><li>گام ۱ (آماده‌سازی بستنی): یک اسکوپ بستنی وانیلی باکیفیت (یا کرمه) به قطر حدود ۵ سانتی‌متر را در یک کاسه یا لیوان دسر (۱۵۰ میلی‌لیتری) قرار دهید. بستنی باید کاملاً سفت و حدود ۴- درجه سانتی‌گراد باشد.</li><li>گام ۲ (دم‌آوری اسپرسو): یک شات اسپرسوی داغ (۹۲ درجه، ۳۶ گرم) را مستقیماً روی بستنی بریزید. (اسپرسو باید تازه‌ترین حالت ممکن را داشته باشد تا گرمای آن با بستنی سرد تضاد ایجاد کند).</li><li>گام ۳ (سرو فوری): بدون هم زدن سرو کنید. بستنی به‌تدریج ذوب شده و با اسپرسو ترکیب میشود. یک بیسکویت یا فندق خردشده کنار آن اضافه کنید.</li><li>نکته: نسبت ایده‌آل: ۱ اسکوپ بستنی به ۱ شات اسپرسو.</li></ul>","kind":"item"},{"id":55,"title":"کافه کورتو (Caffè Corretto)","body":"<ul><li>گام ۱ (آماده‌سازی فنجان): یک فنجان اسپرسو (۹۰ میلی‌لیتری) را گرم کنید.</li><li>گام ۲ (افزودن مشروب): ابتدا یک شات (حدود ۲۰–۳۰ میلی‌لیتر) از مشروب انتخابی (گراپا، براندی، ویسکی، یا لیمونچلو) را در فنجان بریزید. (در ایتالیا، گراپا رایج‌ترین است).</li><li>گام ۳ (دم‌آوری اسپرسو): یک شات اسپرسوی داغ (۳۶ گرم) را روی مشروب بریزید. (اگر مشروب سرد است، اسپرسو آن را گرم می‌کند).</li><li>گام ۴ (سرو): نوشیدنی را با قاشق کوچک هم بزنید و بلافاصله سرو کنید. (معمولاً به‌عنوان نوشیدنی پس از غذا سرو می‌شود).</li><li>نکته: می‌توانید به‌جای شکر، یک تکه پوست لیمو یا پرتقال به لبه فنجان بمالید.</li></ul>","kind":"item"},{"id":56,"title":"اسپرسو رومانو (Espresso Romano)","body":"<ul><li>گام ۱ (آماده‌سازی فنجان): یک فنجان اسپرسو (۹۰ میلی‌لیتری) را گرم کنید.</li><li>گام ۲ (افزودن پوست مرکبات): یک برش نازک از پوست لیموی تازه (بدون بخش سفید تلخ) را در فنجان قرار دهید یا به لبه آن بچسبانید.</li><li>گام ۳ (دم‌آوری اسپرسو): یک شات اسپرسوی ۳۶ گرمی را مستقیماً روی پوست لیمو بریزید. (عطر روغن لیمو با اسپرسو ترکیب می‌شود).</li><li>گام ۴ (سرو): نوشیدنی را هم بزنید و با همان تکه لیمو سرو کنید. برخی دستور‌ها یک حبه قند همراه با لیمو در کنار فنجان قرار می‌دهند.</li><li>نکته: اسپرسو رومانو هرگز حاوی آب لیموی تازه نیست، فقط پوست لیمو عطر می‌دهد.</li></ul>","kind":"item"},{"id":57,"title":"کافه تونیک (Coffee Tonic)","body":"<ul><li>گام ۱ (آماده‌سازی لیوان): یک لیوان بلند (۳۵۰ میلی‌لیتری) را تا نیمه از یخ کیوبی پر کنید.</li><li>گام ۲ (ریختن تونیک): ۱۵۰ میلی‌لیتر آب تونیک (ترجیحاً با کیفیت بالا و گازدار) را روی یخ بریزید.</li><li>گام ۳ (دم‌آوری اسپرسو): یک شات اسپرسوی ۳۶ گرمی را به‌آرامی از پشت قاشق روی تونیک بریزید تا لایه‌بندی حفظ شود. (اسپرسوی داغ روی تونیک سرد باعث ایجاد حباب‌های ظریف و واکنش می‌شود).</li><li>گام ۴ (تزیین): یک برش لیمو یا پرتقال به لبه لیوان اضافه کنید.</li><li>گام ۵ (سرو): نوشیدنی را قبل از هم زدن سرو کنید تا مهمان خود شاهد ترکیب شدن لایه‌ها باشد. پس از هم زدن، نوشیدنی گازدار و با طعمی مرکباتی-قهوه‌ای است.</li><li>نکته: از تونیک بسیار سرد (۴ درجه) و اسپرسوی خیلی تازه استفاده کنید تا حباب‌ها و عطر به‌خوبی آزاد شوند.</li></ul>","kind":"item"},{"id":58,"title":"اسپرسو فیز (Espresso Fizz)","body":"<ul><li>گام ۱ (آماده‌سازی لیوان): یک لیوان بلند (۳۰۰ میلی‌لیتری) را تا نیمه از یخ کیوبی پر کنید.</li><li>گام ۲ (ریختن آب گازدار): ۱۲۰ میلی‌لیتر آب سودا (گازدار بدون قند) را روی یخ بریزید.</li><li>گام ۳ (افزودن اسپرسو): یک شات اسپرسوی ۳۶ گرمی را مستقیم و داغ روی آب سودا بریزید. (واکنش گاز ایجاد شده و کفی ظریف شکل می‌گیرد).</li><li>گام ۴ (افزودن شیرین‌کننده اختیاری): در صورت تمایل، ۱۰–۱۵ میلی‌لیتر شربت ساده (شکر و آب به‌نسبت ۱:۱) یا شربت وانیل به لیوان اضافه کنید.</li><li>گام ۵ (هم زدن و سرو): با قاشق بلند به‌آرامی هم بزنید تا یکدست شود. یک تکه لیمو یا پرتقال برای تزیین اضافه کنید.</li><li>نکته: این نوشیدنی در دهه ۱۹۲۰ در آمریکا رایج بود و نسخه‌ای گازدار و با طراوت از اسپرسو محسوب می‌شود.</li></ul>","kind":"item"}],"hero":"assets/images/espresso_extra.svg"},{"id":"pour_over","icon":"pourover","title":"دم‌آوری ثقلی (پوراوور)","items":[{"id":62,"title":"وی‌شصت (V60)","body":"<ul><li>گام ۱ (تجهیزات): فیلتر کاغذی مخروطی (اندازه ۰۲) را در دریپر V60 قرار دهید. آن را با آب داغ (۹۶ درجه) کاملاً خیس کنید تا طعم کاغذ گرفته شود و دریپر گرم شود. آب خیس‌کننده را دور بریزید.</li><li>گام ۲ (وزن و آسیاب): ۱۵ گرم قهوه دانه‌شده را آسیاب کنید (درجه: متوسط-ریز، مشابه شکر معمولی، حدود ۴۰۰–۵۰۰ میکرون).</li><li>گام ۳ (ریختن قهوه): پودر قهوه را در مرکز فیلتر بریزید و به آرامی تکان دهید تا سطح صاف شود. دریپر را روی کاراف یا فنجان (حداقل ۲۵۰ میلی‌لیتری) قرار دهید.</li><li>گام ۴ (بلوم – خیساندن اولیه): کرونومتر را شروع کنید. ۴۵ میلی‌لیتر آب با دمای ۹۳ درجه سانتی‌گراد را به‌صورت مارپیچ از مرکز به بیرون بر روی قهوه بریزید تا همه ذرات خیس شوند. ۳۰ ثانیه صبر کنید (در این مدت گاز CO₂ خارج شده و حباب‌ها دیده می‌شود).</li><li>گام ۵ (ریختن اصلی – مرحله اول): از دقیقه ۰:۳۰ تا ۱:۱۵، آب را به‌صورت مارپیچ و یکنواخت بریزید تا وزن کل آب به ۱۵۰ گرم برسد (یعنی ۱۰۵ گرم آب اضافه کنید). جریان آب باید نازک و پیوسته باشد.</li><li>گام ۶ (مرحله دوم): از ۱:۱۵ تا ۲:۰۰، ادامه دهید تا وزن کل آب به ۲۵۰ گرم برسد (نسبت نهایی ۱:۱۶.۶). در این مرحله، سطح آب باید همیشه بالای بستر قهوه باشد (بدون این که خشک شود).</li><li>گام ۷ (چکیدن): اجازه دهید آب کاملاً از فیلتر بچکد. زمان کل عصاره‌گیری (از شروع بلوم تا اتمام چکیدن) باید حدود ۳:۰۰ تا ۳:۳۰ دقیقه باشد.</li><li>گام ۸ (سرو): بلافاصله سرو کنید. طعمی شفاف، با اسیدیته روشن و بدنه‌ای سبک تا متوسط.</li></ul>","kind":"item"},{"id":63,"title":"کمکس (Chemex)","body":"<ul><li>گام ۱ (تجهیزات): فیلتر کاغذی مخصوص کمکس (ضخیم‌تر و سنگین‌تر از V60) را به‌صورت مثلثی (یک لایه در یک سمت، سه لایه در سمت دیگر) در قسمت بالایی کاراف شیشه‌ای قرار دهید. آن را با آب داغ خیس کنید و آب آن را خالی کنید.</li><li>گام ۲ (وزن و آسیاب): ۲۲ گرم قهوه را آسیاب کنید (درجه: متوسط-درشت، حدود ۶۰۰–۷۰۰ میکرون، چون فیلتر ضخیم است و عصاره‌گیری کندتری دارد).</li><li>گام ۳ (ریختن قهوه): پودر را در فیلتر بریزید و سطح را صاف کنید.</li><li>گام ۴ (بلوم): ۶۰ میلی‌لیتر آب با دمای ۹۴ درجه را به‌صورت مارپیچ بر روی قهوه بریزید. ۴۵ ثانیه صبر کنید.</li><li>گام ۵ (ریختن اصلی): در ۳ مرحله (هر مرحله ۱۵۰ میلی‌لیتر) آب بریزید تا به کل ۳۷۰ گرم آب برسید (نسبت ۱:۱۶.۸). بین هر مرحله، اجازه دهید سطح آب حدود نصف شود، اما بستر قهوه هرگز خشک نشود. زمان کل ریختن حدود ۴ دقیقه باشد.</li><li>گام ۶ (چکیدن): اجازه دهید آب کاملاً از فیلتر عبور کند (زمان کل حدود ۴:۳۰ تا ۵:۰۰ دقیقه).</li><li>گام ۷ (سرو): کاراف کمکس را تکان دهید تا لایه‌ها یکدست شوند، سپس در فنجان بریزید. طعمی فوق‌العاده تمیز، بدون روغن و با بدنه‌ای سبک و شفاف.</li></ul>","kind":"item"},{"id":64,"title":"کالیتا ویو (Kalita Wave)","body":"<ul><li>گام ۱ (تجهیزات): فیلتر تخت مخصوص (Wave) را در دریپر کف‌صاف (با ۳ سوراخ در کف) قرار دهید. فیلتر را با آب داغ خیس کنید و دور بریزید.</li><li>گام ۲ (وزن و آسیاب): ۲۰ گرم قهوه را آسیاب کنید (درجه: متوسط، حدود ۵۰۰–۶۰۰ میکرون، یکدست‌تر از V60).</li><li>گام ۳ (بلوم): ۵۰ میلی‌لیتر آب با دمای ۹۳ درجه را به‌آرامی و یکنواخت روی تمام سطح قهوه بریزید. ۳۰ ثانیه صبر کنید.</li><li>گام ۴ (ریختن اصلی): آب را به‌صورت پالس‌وار (در ۴ تا ۵ نوبت) بریزید. هر بار ۵۰–۶۰ میلی‌لیتر، صبر کنید تا سطح آب پایین بیاید، سپس دوباره بریزید. کل آب تا ۳۲۰ گرم (نسبت ۱:۱۶) به‌صورت کنترل‌شده اضافه کنید. زمان کل ریختن حدود ۳:۳۰ دقیقه باشد.</li><li>گام ۵ (چکیدن): با کف صاف و سوراخ‌های کوچک، جریان آب یکنواخت‌تر است و زمان نهایی ۳:۳۰ تا ۴:۰۰ دقیقه خواهد بود.</li><li>گام ۶ (سرو): طعمی متعادل‌تر از V60 با بدنه‌ای کمی سنگین‌تر و اسیدیته‌ای ملایم‌تر.</li></ul>","kind":"item"},{"id":65,"title":"ریخته‌گری معمولی/دستی (Pour-Over)","body":"<ul><li>این مدل همان اصول کلی است و می‌توان از هر دریپر معمولی (مانند Melitta یا کتری ساده) استفاده کرد.</li><li>گام ۱: فیلتر کاغذی معمولی (مخروطی یا سبدی) را در دریپر قرار دهید و خیس کنید.</li><li>گام ۲: ۱۵ گرم قهوه با آسیاب متوسط (۵۰۰–۶۰۰ میکرون) بریزید.</li><li>گام ۳: ۵۰ میلی‌لیتر آب (۹۳ درجه) برای بلوم به‌مدت ۳۰ ثانیه بریزید.</li><li>گام ۴: آب را به‌صورت دستی و با یک کتری معمولی (با دقت در کنترل جریان) به‌صورت دورانی و یکنواخت بریزید تا به وزن ۲۵۰ گرم برسد (نسبت ۱:۱۶.۶). زمان کل حدود ۳ دقیقه.</li><li>گام ۵: اجازه دهید آب بچکد و سرو کنید. این روش ساده‌ترین نسخه فیلتری است و برای مبتدیان مناسب است.</li></ul>","kind":"item"}],"hero":"assets/images/pour_over.svg"},{"id":"immersion","icon":"immersion","title":"غوطه‌وری و تحت فشار","items":[{"id":69,"title":"فرنچ پرس (French Press)","body":"<ul><li>گام ۱ (گرم‌کردن): پیستون را از استوانه خارج کرده و استوانه را با آب داغ پر کنید تا گرم شود. سپس آب را خالی کنید.</li><li>گام ۲ (وزن و آسیاب): ۳۰ گرم قهوه را آسیاب کنید (درجه: درشت، حدود ۸۰۰–۹۰۰ میکرون، مشابه نان تست خردشده).</li><li>گام ۳ (ریختن قهوه): پودر قهوه را کف استوانه بریزید.</li><li>گام ۴ (ریختن آب): ۵۰۰ میلی‌لیتر آب با دمای ۹۴ درجه سانتی‌گراد را به‌یکباره روی قهوه بریزید. (نسبت ۱:۱۶.۶).</li><li>گام ۵ (هم‌زدن): با یک قاشق چوبی یا پلاستیکی، به‌آرامی قهوه و آب را هم بزنید تا همه ذرات خیس شوند (حدود ۱۰ ثانیه).</li><li>گام ۶ (قرار دادن پیستون): پیستون را در بالای استوانه قرار دهید (فشار ندهید) تا گرما حفظ شود.</li><li>گام ۷ (زمان غوطه‌وری): کرونومتر را شروع کنید و ۴ دقیقه صبر کنید.</li><li>گام ۸ (شکستن پوسته): پس از ۴ دقیقه، پوسته سطحی را با قاشق بشکنید و به‌آرامی هم بزنید.</li><li>گام ۹ (فشار): پیستون را به‌آرامی و یکنواخت تا انتها فشار دهید (بدون تکان ناگهانی).</li><li>گام ۱۰ (سرو): بلافاصله قهوه را در فنجان بریزید (در صورت باقی‌ماندن در استوانه، تلخی بیشتر می‌شود). طعمی با بدنه سنگین، روغنی و اسیدیته ملایم.</li></ul>","kind":"item"},{"id":70,"title":"موکاپات (Moka Pot – قهوه‌جوش روی اجاق)","body":"<ul><li>گام ۱ (آماده‌سازی قطعات): موکاپات را به سه قسمت (مخزن پایین آب، سبد قهوه، محفظه بالایی) جدا کنید.</li><li>گام ۲ (پر کردن مخزن آب): مخزن پایین را با آب داغ (نه جوش) تا زیر دریچه اطمینان پر کنید (حدود ۲۰۰ میلی‌لیتر برای موکاپات ۶ نفره). از آب گرم استفاده کنید تا سوختن قهوه به حداقل برسد.</li><li>گام ۳ (پر کردن سبد): سبد قهوه را تا لبه با پودر قهوه (آسیاب متوسط-ریز، حدود ۳۰۰–۴۰۰ میکرون) پر کنید. بدون فشار دادن، سطح را با انگشت صاف کنید.</li><li>گام ۴ (مونتاژ): سبد را در مخزن پایین قرار دهید. محفظه بالایی را محکم روی آن ببندید (پیچ کنید).</li><li>گام ۵ (حرارت): موکاپات را روی اجاق گاز با شعله متوسط قرار دهید. دسته باید دور از شعله باشد.</li><li>گام ۶ (عصاره‌گیری): پس از چند دقیقه، قهوه به‌آرامی از لوله مرکزی به محفظه بالا جریان می‌یابد. وقتی جریان تغییر کرد و صدای غارغار (بخار) شنیده شد، بلافاصله موکاپات را از روی حرارت بردارید.</li><li>گام ۷ (سرو): قهوه را هم بزنید و در فنجان‌های کوچک (۵۰–۶۰ میلی‌لیتری) سرو کنید. طعمی غلیظ، نزدیک به اسپرسو اما با بدنه‌ای سنگین‌تر و تلخی ملایم.</li></ul>","kind":"item"},{"id":71,"title":"ایروپرس (AeroPress)","body":"<ul><li>(روش کلاسیک (غیرمعکوس))</li><li>گام ۱ (آماده‌سازی): یک فیلتر کاغذی را در کاپ ایروپرس قرار دهید، آن را با آب داغ خیس کنید و سپس آب آن را خالی کنید. ایروپرس را روی یک فنجان محکم (یا کاراف) قرار دهید.</li><li>گام ۲ (وزن و آسیاب): ۱۵ گرم قهوه را آسیاب کنید (درجه: متوسط-ریز، حدود ۳۰۰–۴۰۰ میکرون، مشابه نمک دریایی ریز).</li><li>گام ۳ (ریختن قهوه): پودر را داخل استوانه ایروپرس بریزید.</li><li>گام ۴ (ریختن آب): ۲۵۰ میلی‌لیتر آب با دمای ۹۳ درجه را به‌یکباره روی قهوه بریزید. (نسبت ۱:۱۶.۶).</li><li>گام ۵ (هم‌زدن): با هم‌زن مخصوص (یا قاشق چوبی) به‌مدت ۱۰ ثانیه به‌آرامی هم بزنید.</li><li>گام ۶ (قرار دادن پیستون): پیستون را در بالای استوانه قرار دهید (نچسبانید) تا از چکیدن جلوگیری شود.</li><li>گام ۷ (زمان غوطه‌وری): ۱ دقیقه تا ۱:۳۰ صبر کنید.</li><li>گام ۸ (فشار): پیستون را به‌آرامی و با فشار ثابت (حدود ۱۵–۲۰ کیلوگرم) تا انتها فشار دهید (زمان فشار حدود ۲۰–۳۰ ثانیه).</li><li>گام ۹ (سرو): قهوه را با آب داغ رقیق کنید (در صورت تمایل) یا همان‌طور سرو کنید. طعمی تمیز، با بدنه متوسط و بسیار سازگار.</li></ul><p>(روش معکوس – اینورت: همه مراحل بالا، اما ایروپرس را برعکس (پیستون در پایین) قرار دهید، پس از هم‌زدن و غوطه‌وری، آن را روی فنجان برگردانید و فشار دهید.)</p>","kind":"item"},{"id":72,"title":"کلور دریپر (Clever Dripper)","body":"<ul><li>گام ۱ (آماده‌سازی): یک فیلتر کاغذی (اندازه ۴) را در دریپر قرار دهید، با آب داغ خیس کنید و آب آن را خالی کنید. دریپر را روی فنجان یا کاراف قرار دهید و دریچه تخلیه را ببندید.</li><li>گام ۲ (وزن و آسیاب): ۲۰ گرم قهوه را آسیاب کنید (درجه: متوسط، حدود ۵۰۰–۶۰۰ میکرون).</li><li>گام ۳ (ریختن قهوه و آب): پودر را در فیلتر بریزید و ۳۰۰ میلی‌لیتر آب با دمای ۹۳ درجه را یکجا روی آن بریزید (نسبت ۱:۱۵).</li><li>گام ۴ (هم‌زدن): به‌آرامی هم بزنید تا همه ذرات خیس شوند (۱۰ ثانیه).</li><li>گام ۵ (غوطه‌وری): کرونومتر را شروع کنید و ۲:۳۰ دقیقه صبر کنید.</li><li>گام ۶ (تخلیه): کلور دریپر را روی فنجان قرار دهید (دریچه باز می‌شود) و اجازه دهید قهوه به‌طور کامل تخلیه شود (حدود ۳۰–۴۰ ثانیه).</li><li>گام ۷ (سرو): طعمی ترکیبی از غوطه‌وری (بدنه) و فیلتراسیون (تمیزی) – بسیار متعادل.</li></ul>","kind":"item"},{"id":73,"title":"سیفون (Siphon / Vacuum Pot)","body":"<ul><li>گام ۱ (تجهیزات): سیفون را مونتاژ کنید: محفظه پایین (کره یا استوانه) را با آب گرم (۵۰۰ میلی‌لیتر) پر کنید. فیلتر (معمولاً پارچه‌ای یا شیشه‌ای) را در محفظه بالایی قرار دهید و با فنر محکم کنید.</li><li>گام ۲ (حرارت): محفظه پایین را روی منبع حرارت (لامپ الکلی، هالوژن یا اجاق) قرار دهید تا آب به جوش آید.</li><li>گام ۳ (ورود قهوه): وقتی آب شروع به جوشیدن کرد و به محفظه بالا رفت (فشار بخار)، ۳۰ گرم قهوه با آسیاب متوسط (۵۰۰ میکرون) را به محفظه بالایی اضافه کنید.</li><li>گام ۴ (هم‌زدن): با هم‌زن مخصوص، قهوه را به‌آرامی هم بزنید (۱۰ ثانیه) تا همه ذرات با آب مخلوط شوند.</li><li>گام ۵ (زمان): کرونومتر را شروع کنید و ۱:۳۰ دقیقه صبر کنید.</li><li>گام ۶ (قطع حرارت): پس از ۱:۳۰، منبع حرارت را بردارید. با سرد شدن محفظه پایین، خلأ ایجاد شده و قهوه از طریق فیلتر به محفظه پایین برمی‌گردد.</li><li>گام ۷ (سرو): پس از تخلیه کامل (حدود ۱ دقیقه دیگر)، سیفون را باز کنید و قهوه را در فنجان بریزید. طعمی لطیف، شفاف و با عطر بسیار زیاد.</li></ul>","kind":"item"},{"id":74,"title":"پرکولاتور (Percolator)","body":"<ul><li>گام ۱ (آماده‌سازی): مخزن پایینی پرکولاتور را با آب سرد پر کنید (تا زیر لوله مرکزی).</li><li>گام ۲ (سبد قهوه): سبد قهوه را پر کنید (۱۰ گرم قهوه به ازای هر ۱۰۰ میلی‌لیتر آب، آسیاب درشت) و آن را روی لوله مرکزی قرار دهید.</li><li>گام ۳ (حرارت): درب را ببندید و روی اجاق با حرارت متوسط قرار دهید.</li><li>گام ۴ (جوشیدن): وقتی آب به جوش آمد، از طریق لوله به بالا رانده شده و بر روی قهوه می‌چکد. این چرخه (جوشیدن و چکیدن) را به‌مدت ۵–۷ دقیقه ادامه دهید.</li><li>گام ۵ (برداشتن): حرارت را خاموش کنید و قهوه را بلافاصله سرو کنید.</li><li>نکته: مراقب باشید زمان بیشتر از ۷ دقیقه نشود، زیرا قهوه بسیار تلخ و سوخته می‌شود (چون آب داغ مدام از میان قهوه عبور می‌کند).</li></ul>","kind":"item"}],"hero":"assets/images/immersion.svg"},{"id":"drip","icon":"autodrip","title":"قطره‌ای و اتوماتیک","items":[{"id":78,"title":"قهوه‌ساز قطره‌ای صنعتی (Batch Brew – مانند Fetco یا Curtis)","body":"<ul><li>گام ۱ (آماده‌سازی دستگاه): دستگاه را روشن کرده و مخزن آب را با آب تصفیه‌شده پر کنید. اجازه دهید تا دمای آب به ۹۲–۹۴ درجه سانتی‌گراد برسد (دستگاه‌های صنعتی معمولاً تنظیمات دما دارند).</li><li>گام ۲ (آماده‌سازی فیلتر): یک فیلتر کاغذی بزرگ (سبدی یا مخروطی سایز بزرگ) را در سبد فیلتر دستگاه قرار دهید. آن را با آب داغ خیس کنید تا طعم کاغذ گرفته شود و سپس آب خیس‌کننده را دور بریزید.</li><li>گام ۳ (وزن و آسیاب): برای هر لیتر آب، ۶۰ گرم قهوه در نظر بگیرید (نسبت استاندارد ۱:۱۶.۶). مثلاً برای ۲ لیتر آب، ۱۲۰ گرم قهوه را آسیاب کنید (درجه: متوسط، حدود ۵۰۰–۶۰۰ میکرون، مشابه شن و ماسه درشت).</li><li>گام ۴ (ریختن قهوه): پودر قهوه را به‌طور یکنواخت در سراسر فیلتر پخش کنید. با یک قاشق، سطح را صاف کرده و یک گودال کوچک در مرکز ایجاد کنید تا آب به‌خوبی نفوذ کند.</li><li>گام ۵ (شروع عصاره‌گیری): دکمه استارت دستگاه را بزنید. دستگاه آب داغ را به‌صورت چرخه‌ای (پالس‌وار) روی بستر قهوه می‌ریزد. فرآیند بلوم (خیساندن اولیه) به‌صورت خودکار انجام می‌شود (چند ثانیه مکث).</li><li>گام ۶ (زمان عصاره‌گیری): کل فرآیند برای یک ظرف کامل (۲–۳ لیتر) حدود ۴ تا ۶ دقیقه طول می‌کشد.</li><li>گام ۷ (سرو و نگهداری): پس از اتمام، قهوه را در قمقمه مخصوص (تراول‌پات) بریزید تا دما را حفظ کند. اگر بیش از ۳۰ دقیقه روی منبع گرمایش باقی بماند، تلخ می‌شود. طعمی متعادل، با بدنه متوسط و اسیدیته ملایم – مناسب برای سرو حجم بالا در کافه‌ها و رستوران‌ها.</li></ul>","kind":"item"},{"id":79,"title":"قهوه‌ساز قطره‌ای خانگی (Home Drip Coffee Maker)","body":"<ul><li>گام ۱ (آماده‌سازی دستگاه): دستگاه را روشن کرده و مخزن آب را با آب سرد تصفیه‌شده پر کنید (میزان آب را بر اساس تعداد فنجان‌های مورد نظر تنظیم کنید). اگر دستگاه دارای تنظیم دما است، آن را روی ۹۲ درجه قرار دهید.</li><li>گام ۲ (آماده‌سازی فیلتر): یک فیلتر کاغذی سایز مناسب (سبدی یا مخروطی #۴) را در سبد فیلتر قرار دهید. آن را با آب داغ خیس کنید (با ریختن آب از کتری روی آن) و آب خیس‌کننده را خالی کنید.</li><li>گام ۳ (وزن و آسیاب): به ازای هر فنجان (۱۸۰ میلی‌لیتر آب)، ۱۱ گرم قهوه استفاده کنید. مثلاً برای ۶ فنجان (حدود ۱ لیتر آب)، ۶۰ گرم قهوه را آسیاب کنید (درجه: متوسط-ریز، حدود ۴۰۰–۵۰۰ میکرون، کمی ریزتر از دستگاه صنعتی چون حجم آب کمتر است).</li><li>گام ۴ (ریختن قهوه): پودر را به‌صورت یکنواخت در فیلتر پخش کنید. سطح را صاف کنید.</li><li>گام ۵ (شروع دستگاه): دکمه استارت یا برنامه‌ریزی را بزنید. آب داغ از طریق سرریزکننده (شاورهد) روی قهوه پاشیده می‌شود.</li><li>گام ۶ (فرآیند دم‌آوری): کل فرآیند معمولاً ۴ تا ۵ دقیقه طول می‌کشد. در برخی دستگاه‌ها، می‌توانید با باز کردن دریچه سبد فیلتر در ۳۰ ثانیه اول (بلوم دستی) و بستن آن، کیفیت را بهبود دهید (اگر دستگاه اجازه دهد).</li><li>گام ۷ (پایان و سرو): پس از اتمام چکیدن، قهوه را از قابلمه شیشه‌ای یا قمقمه داخل فنجان بریزید. اگر قهوه روی صفحه گرمکن باقی بماند، حداکثر تا ۲۰ دقیقه قابل‌قبول است (پس از آن تلخی و سوختگی ایجاد می‌شود). برای بهترین نتیجه، قهوه را بلافاصله سرو کنید.</li></ul>","kind":"item"}],"hero":"assets/images/drip.svg"},{"id":"cold","icon":"cold","title":"سرد و یخی","items":[{"id":85,"title":"کلد برو (Cold Brew)","body":"<ul><li>گام ۱ (آماده‌سازی ظرف): یک ظرف شیشه‌ای یا پارچ بزرگ (با درب) را آماده کنید.</li><li>گام ۲ (وزن و آسیاب): ۱۰۰ گرم قهوه را آسیاب کنید (درجه: درشت، حدود ۸۰۰–۹۰۰ میکرون، مشابه نان تست خردشده).</li><li>گام ۳ (ریختن قهوه و آب): پودر قهوه را در ظرف بریزید و ۸۰۰ میلی‌لیتر آب سرد (دمای اتاق یا ۲۰ درجه) به آن اضافه کنید (نسبت ۱:۸). با یک قاشق چوبی به‌آرامی هم بزنید تا همه ذرات خیس شوند.</li><li>گام ۴ (خیساندن): درب ظرف را ببندید و به‌مدت ۱۲ تا ۲۴ ساعت در یخچال (۴ درجه سانتی‌گراد) قرار دهید. (زمان ۱۶ ساعت برای تعادل طعم ایده‌آل است).</li><li>گام ۵ (صاف‌کردن): پس از خیساندن، قهوه را از یک پارچه مخصوص (یا فیلتر کاغذی ضخیم) عبور دهید تا تفاله‌ها کاملاً جدا شوند. ممکن است نیاز به دو بار صاف‌کردن باشد.</li><li>گام ۶ (رقیق‌کردن و سرو): کنسانتره کلد برو را با آب سرد یا شیر به نسبت ۱:۱ (یا ۱:۲) رقیق کنید. روی یخ سرو کنید. طعمی با اسیدیته بسیار پایین، شیرینی طبیعی و بدنه‌ای نرم و شکلاتی.</li><li>نگهداری: کنسانتره تا ۲ هفته در یخچال قابل‌نگهداری است.</li></ul>","kind":"item"},{"id":86,"title":"نیترو کلد برو (Nitro Cold Brew)","body":"<ul><li>گام ۱: یک دسته کلد برو (طبق روش بالا) تهیه کنید و آن را رقیق نکنید (کنسانتره خالص).</li><li>گام ۲ (تجهیزات): کنسانتره را در یک مخزن مخصوص (Keg) بریزید و آن را با گاز نیتروژن (N₂) تحت فشار (۳۰–۴۰ psi) قرار دهید. (برای مصارف خانگی، از دستگاه‌های Nitro Cold Brew خانگی یا قوطی‌های شارژ نیترو استفاده کنید).</li><li>گام ۳ (تزریق): نوشیدنی را از شیر مخصوص (با نازل) به‌آرامی در لیوان بریزید. نیتروژن باعث ایجاد حباب‌های ریز و کفی غلیظ و کرم‌مانند می‌شود (مانند آبجو).</li><li>گام ۴ (سرو): بدون یخ سرو کنید (چون خود نوشیدنی سرد و کرمی است). طعمی فوق‌العاده نرم، با کفی پایدار و شیرینی طبیعی.</li></ul>","kind":"item"},{"id":87,"title":"آیس فیلتر / ژاپنی (Iced Pour-Over / Japanese Iced)","body":"<ul><li>گام ۱ (آماده‌سازی لیوان): یک لیوان بلند (۳۰۰ میلی‌لیتری) را تا نیمه از یخ کیوبی پر کنید.</li><li>گام ۲ (تجهیزات فیلتری): یک دریپر V60 یا کمکس را روی لیوان قرار دهید. فیلتر را خیس کنید و آب آن را خالی کنید.</li><li>گام ۳ (وزن و آسیاب): ۱۵ گرم قهوه را آسیاب کنید (درجه: متوسط-ریز، حدود ۴۰۰–۵۰۰ میکرون، اما کمی ریزتر از روش داغ معمولی).</li><li>گام ۴ (بلوم): ۴۵ میلی‌لیتر آب با دمای ۹۳ درجه را روی قهوه بریزید و ۳۰ ثانیه صبر کنید.</li><li>گام ۵ (ریختن اصلی): آب داغ را به‌صورت مارپیچ بریزید تا وزن کل آب به ۲۵۰ گرم برسد (نسبت ۱:۱۶.۶) – اما زمان کل ریختن باید حدود ۲:۳۰ دقیقه باشد (سریع‌تر از روش داغ). آب داغ روی یخ می‌چکد و فوراً سرد می‌شود.</li><li>گام ۶ (سرو): پس از اتمام چکیدن، لیوان را به‌آرامی تکان دهید و با یک برش لیمو یا پرتقال تزیین کنید. طعمی شفاف، با اسیدیته روشن و طراوت بالا.</li></ul>","kind":"item"},{"id":88,"title":"فراپه یونانی (Greek Frappe)","body":"<ul><li>گام ۱ (آماده‌سازی شیکر): یک شیکر یا ظرف درب‌دار (مانند شیشه مربا) را آماده کنید.</li><li>گام ۲ (مواد اصلی): ۲ قاشق چای‌خوری (۶–۸ گرم) قهوه فوری (Nescafe یا مشابه) را در شیکر بریزید. ۲ قاشق چای‌خوری شکر (در صورت تمایل) و ۵۰ میلی‌لیتر آب سرد به آن اضافه کنید.</li><li>گام ۳ (هم‌زدن): درب را ببندید و به‌مدت ۳۰ تا ۴۰ ثانیه به‌شدت تکان دهید تا کفی غلیظ و براق ایجاد شود.</li><li>گام ۴ (سرو): یک لیوان بلند را تا نیمه از یخ پر کنید. کف قهوه را روی یخ بریزید و سپس ۱۰۰ میلی‌لیتر آب سرد (یا شیر) به آن اضافه کنید.</li><li>گام ۵ (تزیین): با نی سرو کنید و در صورت تمایل، یک لایه شیر روی آن بریزید. نوشیدنی بسیار گازدار و کف‌دار با طعمی قوی و شیرین.</li></ul>","kind":"item"},{"id":89,"title":"فراپوچینو (Frappuccino – نسخه خانگی)","body":"<ul><li>گام ۱ (آماده‌سازی مخلوط‌کن): یک مخلوط‌کن قوی (بلندر) را آماده کنید.</li><li>گام ۲ (مواد): در بلندر بریزید: ۱۰۰ میلی‌لیتر اسپرسوی سرد (یا قهوه غلیظ دم‌شده و سرد)، ۱۵۰ میلی‌لیتر شیر کامل، ۲ قاشق غذاخوری شکر (یا شربت وانیل)، ۱ لیوان پر از یخ کیوبی (حدود ۱۵۰ گرم)، و در صورت تمایل ۳۰ میلی‌لیتر شربت کارامل یا شکلات.</li><li>گام ۳ (مخلوط‌کردن): با سرعت بالا به‌مدت ۳۰–۴۰ ثانیه مخلوط کنید تا یخ کاملاً پودر شده و بافت یکدست و کرم‌مانند شود.</li><li>گام ۴ (سرو): در لیوان بلند بریزید و با خامه فرم‌گرفته و سس کارامل یا شکلات تزیین کنید. طعمی شیرین، یخی و بافتی شبیه میلک‌شیک با قهوه.</li></ul>","kind":"item"},{"id":90,"title":"شیکراتو (Shakerato – اسپرسوی تکان‌داده‌شده با یخ)","body":"<ul><li>گام ۱ (آماده‌سازی شیکر): یک شیکر کوکتل (یا ظرف درب‌دار) را با یخ کیوبی پر کنید.</li><li>گام ۲ (مواد): یک شات اسپرسوی داغ (۳۶ گرم) و ۱۵ میلی‌لیتر شربت ساده (شکر+آب به نسبت ۱:۱) را در شیکر بریزید.</li><li>گام ۳ (تکان‌دادن): درب شیکر را محکم ببندید و به‌مدت ۳۰–۴۰ ثانیه به‌شدت تکان دهید تا نوشیدنی کاملاً سرد و کف‌دار شود.</li><li>گام ۴ (صاف‌کردن): نوشیدنی را از صافی شیکر در یک لیوان مارتینی یا لیوان بلند (بدون یخ) بریزید.</li><li>گام ۵ (سرو): یک لایه کف ریز روی سطح تشکیل می‌شود. با پوست پرتقال تزیین کنید. طعمی قوی، سرد و با طراوت.</li></ul>","kind":"item"},{"id":91,"title":"آیس لاته (Iced Latte)","body":"<ul><li>گام ۱ (آماده‌سازی لیوان): یک لیوان بلند (۳۵۰ میلی‌لیتری) را تا نیمه از یخ کیوبی پر کنید.</li><li>گام ۲ (ریختن شیر): ۱۵۰ میلی‌لیتر شیر کامل سرد را روی یخ بریزید.</li><li>گام ۳ (افزودن اسپرسو): یک شات اسپرسوی داغ (۳۶ گرم) را به‌آرامی روی شیر بریزید (ترجیحاً از پشت قاشق).</li><li>گام ۴ (هم‌زدن): با قاشق بلند ۲–۳ بار به‌آرامی هم بزنید تا لایه‌ها تا حدی ترکیب شوند.</li><li>گام ۵ (سرو): در صورت تمایل، شربت وانیل یا کارامل اضافه کنید. طعمی سرد، شیرین و با بافتی مایع و سبک.</li></ul>","kind":"item"},{"id":92,"title":"آیس ماکیاتو (Iced Macchiato)","body":"<ul><li>گام ۱ (آماده‌سازی لیوان): یک لیوان بلند را تا نیمه از یخ کیوبی پر کنید.</li><li>گام ۲ (ریختن شیر): ۱۵۰ میلی‌لیتر شیر کامل سرد را روی یخ بریزید.</li><li>گام ۳ (افزودن اسپرسو – معکوس): یک شات اسپرسوی داغ (۳۶ گرم) را به‌آرامی از وسط روی شیر بریزید تا یک لکه قهوه‌ای در مرکز سطح شیر ایجاد شود.</li><li>گام ۴ (تزیین): یک لایه نازک کف شیر خشک (که از بافت‌دهی شیر سرد با همزن دستی به‌دست آمده) روی سطح قرار دهید.</li><li>گام ۵ (سرو): بدون هم زدن سرو کنید تا مهمان خود لایه‌بندی (شیر سفید پایین، لکه قهوه در وسط) را ببیند.</li></ul>","kind":"item"}],"hero":"assets/images/cold.svg"},{"id":"traditional","icon":"traditional","title":"سنتی، منطقه‌ای و تاریخی","items":[{"id":96,"title":"قهوه ترک (Turkish Coffee)","body":"<ul><li>گام ۱ (آماده‌سازی جذوه): یک جذوه مسی یا برنجی (ترکی) را با آب سرد (۵۰ میلی‌لیتر به ازای هر فنجان) پر کنید.</li><li>گام ۲ (افزودن قهوه و شکر): به ازای هر فنجان، ۱ قاشق غذاخوری (۷ گرم) قهوه با آسیاب فوق‌ریز (مشابه پودر تالک) و شکر به‌میزان دلخواه (ساده، کم‌شیرین یا شیرین) به جذوه اضافه کنید. هم نزنید؛ فقط اجازه دهید مواد روی سطح آب بنشینند.</li><li>گام ۳ (هل اختیاری): در صورت تمایل، ۱ عدد هل کوبیده‌شده به جذوه اضافه کنید.</li><li>گام ۴ (حرارت): جذوه را روی حرارت خیلی ملایم (اجاق گاز با شعله پخش‌کننده) قرار دهید. به‌هیچ‌وجه هم نزنید تا کف (فوم) به‌خوبی تشکیل شود.</li><li>گام ۵ (بالاآمدن کف): وقتی قهوه شروع به گرم شدن کرد، یک لایه کف طلایی روی سطح تشکیل می‌شود. درست قبل از جوشیدن (وقتی کف به لبه جذوه رسید)، جذوه را از روی حرارت بردارید و کف را با قاشق بین فنجان‌ها تقسیم کنید.</li><li>گام ۶ (جوشاندن دوم): جذوه را دوباره روی حرارت بگذارید تا دوباره کف کند (اما نجوشد). سپس از روی حرارت بردارید.</li><li>گام ۷ (سرو): قهوه را به‌آرامی در فنجان‌های کوچک بریزید (تا تفاله ته ننشیند). ۲–۳ دقیقه صبر کنید تا تفاله ته‌نشین شود، سپس سرو کنید. همراه با یک لیوان آب و یک تکه شکلات یا لقمه.</li></ul>","kind":"item"},{"id":97,"title":"قهوه قجری (Persian Qajar Coffee)","body":"<ul><li>گام ۱ (آماده‌سازی دانه): دانه‌های قهوه را به‌صورت سنتی در تابه چدنی برشته کنید تا عطرشان آزاد شود (تا حدی که کمی دود کنند). سپس در هاون چوبی یا سنگی بکوبید تا پودری درشت‌تر از ترکی (اما ریزتر از فرنچ‌پرس) شود.</li><li>گام ۲ (آماده‌سازی دله/قوری مسی): یک قوری مسی (دله) را با آب سرد پر کنید (۵۰ میلی‌لیتر به ازای هر فنجان).</li><li>گام ۳ (افزودن قهوه و ادویه): به ازای هر فنجان، ۱.۵ قاشق غذاخوری (۱۰ گرم) از پودر قهوه را در دله بریزید. یک تکه نبات (یا شکر) و کمی هل ساییده‌شده و در صورت تمایل، یک نوک قاشق زعفران دم‌شده اضافه کنید.</li><li>گام ۴ (دم‌آوری روی ذغال): دله را روی منقل ذغال یا حرارت بسیار ملایم قرار دهید. قهوه را به‌آرامی حرارت دهید تا به‌آرامی گرم شود (نجوشد). کف سطحی تشکیل می‌شود.</li><li>گام ۵ (برداشتن از حرارت): وقتی کف شروع به جمع شدن کرد، دله را از روی حرارت بردارید و اجازه دهید کف فروکش کند. این کار را ۲ تا ۳ بار تکرار کنید (هر بار از روی حرارت بردارید تا کف فروکش کند و دوباره حرارت دهید).</li><li>گام ۶ (سرو): قهوه را به‌آرامی در فنجان‌های کوچک (بدون نریختن تفاله) بریزید. با یک لیوان آب گلاب و نبات یا خرما سرو کنید. این روش تفاوتش با ترکی در استفاده از زعفران، نبات و کوبیدن دانه در هاون به‌جای آسیاب صنعتی است.</li><li>فال قهوه: پس از نوشیدن، تفاله برای فال قهوه به‌کار می‌رود (تاریخچه قجری).</li></ul>","kind":"item"},{"id":98,"title":"قهوه عربی (Arabic Gahwa)","body":"<ul><li>گام ۱ (برشته‌کاری): دانه‌های قهوه را به‌رنگ قهوه‌ای متوسط تا تیره برشته کنید (تا حدی که کمی دود کنند و روغنشان خارج شود). سپس بکوبید تا پودری درشت شود.</li><li>گام ۲ (آماده‌سازی دله): دله (ظرف مخصوص عربی) را با آب سرد پر کنید و قهوه را اضافه کنید (۱ قاشق غذاخوری به ازای هر فنجان).</li><li>گام ۳ (ادویه‌جات): هل کوبیده‌شده (۲–۳ عدد)، زعفران (یک نوک قاشق) و کمی دارچین اضافه کنید. (بدون شکر).</li><li>گام ۴ (حرارت): روی حرارت ملایم قرار دهید تا قهوه بجوشد و کف کند. پس از جوشیدن، آن را از روی حرارت بردارید و ۱ دقیقه صبر کنید، سپس دوباره بجوشانید. این کار را ۳ بار تکرار کنید.</li><li>گام ۵ (سرو): در فنجان‌های کوچک (بدون دسته) بریزید و همراه با خرما سرو کنید. طعمی تلخ، با عطر هل و زعفران.</li></ul>","kind":"item"},{"id":99,"title":"قهوه اتیوپی (Ethiopian Buna / Jebena)","body":"<ul><li>گام ۱ (برشته‌کاری تازه): دانه‌های قهوه سبز را در تابه روی حرارت تا زمانی که ترک بخورند و عطرشان آزاد شود، برشته کنید. سپس در هاون چوبی بکوبید تا پودری متوسط شود.</li><li>گام ۲ (آماده‌سازی جبنه): کتری سفالی (جبنه) را با آب سرد پر کنید و پودر قهوه را به آن اضافه کنید (۱ قاشق غذاخوری به ازای هر فنجان).</li><li>گام ۳ (دم‌آوری): جبنه را روی منقل یا اجاق قرار دهید تا قهوه بجوشد و کف کند (حدود ۱۰–۱۵ دقیقه). هر بار که کف بالا آمد، جبنه را تکان دهید تا کف فروکش کند.</li><li>گام ۴ (صاف‌کردن): پس از جوشیدن، قهوه را از یک صافی (معمولاً از جنس موی اسب) عبور دهید تا تفاله‌ها جدا شوند.</li><li>گام ۵ (مراسم سه دور): قهوه را در فنجان‌های کوچک بریزید و در سه نوبت سرو کنید: آبُول (دور اول – قوی‌ترین)، تونا (دور دوم – رقیق‌تر) و براکا (دور سوم – شیرین‌ترین). با بخور کندر همراه است.</li></ul>","kind":"item"},{"id":100,"title":"قهوه تخم‌مرغ ویتنامی (Vietnamese Egg Coffee)","body":"<ul><li>گام ۱ (آماده‌سازی کف تخم‌مرغ): یک عدد زرده تخم‌مرغ را با ۲ قاشق غذاخوری شیر تغلیظ‌شده شیرین و ۱ قاشق چای‌خوری عصاره وانیل در یک کاسه بریزید. با همزن برقی به‌مدت ۲–۳ دقیقه هم بزنید تا کفی غلیظ، براق و کش‌دار (مشابه خامه) تشکیل شود.</li><li>گام ۲ (دم‌آوری قهوه): یک شات اسپرسوی غلیظ (یا قهوه روبوستای ویتنامی دم‌شده با فیلتر ساده) را در فنجان بریزید.</li><li>گام ۳ (ترکیب): کف تخم‌مرغ را به‌آرامی روی قهوه بریزید (لایه‌بندی).</li><li>گام ۴ (سرو): در یک کاسه آب گرم قرار دهید تا داغ بماند. با قاشق میل کنید (کف خامه‌ای با قهوه تلخ ترکیب می‌شود). طعمی شبیه دسر کارامل-قهوه.</li></ul>","kind":"item"},{"id":101,"title":"بومبون اسپانیایی (Spanish Bombón)","body":"<ul><li>گام ۱ (آماده‌سازی لیوان): یک لیوان شیشه‌ای کوچک (۱۰۰ میلی‌لیتری) بردارید.</li><li>گام ۲ (شیر تغلیظ‌شده): ۳۰ میلی‌لیتر شیر تغلیظ‌شده شیرین را کف لیوان بریزید.</li><li>گام ۳ (افزودن اسپرسو): یک شات اسپرسوی داغ (۳۶ گرم) را به‌آرامی (پشت قاشق) روی شیر تغلیظ‌شده بریزید تا لایه‌بندی حفظ شود (شیر در پایین، اسپرسو در بالا).</li><li>گام ۴ (سرو): بدون هم زدن سرو کنید. هر لایه به‌تنهایی مزه‌دار است – ترکیب شیرینی شدید و تلخی اسپرسو.</li></ul>","kind":"item"},{"id":102,"title":"کافه‌اوست فنلاندی (Finnish Kaffeost)","body":"<ul><li>گام ۱ (آماده‌سازی پنیر): تکه‌های پنیر اسکیم (Leipäjuusto – پنیر قالبی فنلاندی) را به مکعب‌های ۲ سانتی‌متری برش دهید.</li><li>گام ۲ (دم‌آوری قهوه): یک فنجان قهوه سیاه داغ (فیلتری یا فرنچ‌پرس) آماده کنید.</li><li>گام ۳ (افزودن پنیر): مکعب‌های پنیر را در فنجان قهوه بریزید.</li><li>گام ۴ (سرو): اجازه دهید پنیر ۱–۲ دقیقه در قهوه گرم بماند تا کمی نرم شود. با قاشق میل کنید – ترکیبی از قهوه تلخ و پنیر شور-شیرین.</li></ul>","kind":"item"},{"id":103,"title":"قهوه ایرلندی (Irish Coffee)","body":"<ul><li>گام ۱ (آماده‌سازی لیوان): یک لیوان مقاوم به حرارت (۲۵۰ میلی‌لیتری) را با آب داغ گرم کنید.</li><li>گام ۲ (ویسکی و شکر): آب را خالی کنید. ۳۰ میلی‌لیتر ویسکی ایرلندی و ۲ قاشق چای‌خوری شکر قهوه‌ای (یا شربت شکر) را در لیوان بریزید.</li><li>گام ۳ (قهوه داغ): ۱۵۰ میلی‌لیتر قهوه سیاه داغ (فیلتری قوی) را روی ویسکی و شکر بریزید و هم بزنید تا شکر حل شود.</li><li>گام ۴ (خامه): خامه پرچرب (۳۰٪ چربی) را به‌آرامی روی پشت قاشق روی قهوه بریزید تا یک لایه ضخیم و شناور تشکیل شود (خامه با قهوه مخلوط نشود).</li><li>گام ۵ (سرو): بدون نی و بدون هم زدن سرو کنید تا لایه‌بندی حفظ شود.</li></ul>","kind":"item"},{"id":104,"title":"کافه آوله (Café au Lait – فرانسوی)","body":"<ul><li>گام ۱ (دم‌آوری قهوه فیلتری): یک فنجان قهوه فیلتری (فرنچ‌پرس یا کمکس) به‌حجم ۱۵۰ میلی‌لیتر آماده کنید (نسبت ۱:۱۶).</li><li>گام ۲ (شیر بخارزده): ۱۵۰ میلی‌لیتر شیر کامل را روی حرارت بگذارید تا داغ شود (۶۰–۶۵ درجه) اما کف نداشته باشد (فقط بخار بدهید).</li><li>گام ۳ (ترکیب): قهوه و شیر را به‌نسبت مساوی (۱:۱) در یک کاسه یا فنجان بزرگ بریزید.</li><li>گام ۴ (سرو): بدون کف سرو کنید. طعمی ملایم و نرم.</li></ul>","kind":"item"},{"id":105,"title":"وینر ملانژ (Wiener Melange – اتریش)","body":"<ul><li>گام ۱: یک لونگو (اسپرسوی کشیده – ۵۰ میلی‌لیتر) آماده کنید.</li><li>گام ۲: شیر را بافت‌دهی کنید تا میکروفوم با کف متوسط (۵۵ درجه).</li><li>گام ۳: شیر بخارزده را در فنجان بزرگ بریزید، سپس لونگو را به‌آرامی روی آن بریزید.</li><li>گام ۴: یک لایه کف شیر روی سطح قرار دهید و کمی پودر کاکائو بپاشید. شبیه کاپوچینو اما با لونگو (حجم بیشتر) و کف نرم‌تر.</li></ul>","kind":"item"},{"id":106,"title":"کورتادیتوی کوبایی (Cuban Cortadito)","body":"<ul><li>گام ۱ (اسپرسو با شکر فوم‌شده): ۳۶ گرم اسپرسو دم کنید. هم‌زمان، ۱ قاشق چای‌خوری شکر را با ۵ میلی‌لیتر اسپرسوی اول (چند قطره) در یک فنجان کوچک با قاشق بمالید تا خمیری فوم‌دار و براق تشکیل شود.</li><li>گام ۲: اسپرسوی باقی‌مانده را روی خمیر شکر بریزید و هم بزنید.</li><li>گام ۳: ۳۰ میلی‌لیتر شیر بخارزده (با کف کم) را اضافه کنید. نسبت ۱:۱ اسپرسو و شیر.</li><li>گام ۴ (سرو): در فنجان کوچک با کفی شیرین روی سطح.</li></ul>","kind":"item"},{"id":107,"title":"کافه‌زینهو برزیلی (Brazilian Cafezinho)","body":"<ul><li>گام ۱ (آماده‌سازی فیلتر پارچه‌ای): یک فیلتر پارچه‌ای (یا کاغذی) را روی یک قیف قرار دهید.</li><li>گام ۲ (ادویه‌جات): ۱۵ گرم قهوه آسیاب‌شده (متوسط) را با ۱ عدد میخک، ۱ تکه دارچین، ۱ عدد هل و ۲ قاشق غذاخوری شکر مخلوط کنید.</li><li>گام ۳ (دم‌آوری): ۲۵۰ میلی‌لیتر آب جوش را به‌آرامی روی مخلوط بریزید (مشابه پوراوور).</li><li>گام ۴ (سرو): در فنجان‌های کوچک بریزید. بسیار شیرین و معطر.</li></ul>","kind":"item"},{"id":108,"title":"قهوه ادویه‌دار مغربی (Moroccan Spiced Coffee)","body":"<ul><li>گام ۱: ۱۵ گرم قهوه آسیاب‌شده (متوسط-درشت) را در جذوه یا قوری بریزید.</li><li>گام ۲: ادویه‌جات: ۱/۴ قاشق چای‌خوری فلفل سیاه، ۱/۲ قاشق چای‌خوری دارچین، ۱/۴ قاشق چای‌خوری زنجبیل، ۲ عدد هل، و یک پیمانه زعفران (اختیاری) را اضافه کنید.</li><li>گام ۳: ۳۰۰ میلی‌لیتر آب سرد اضافه کنید و روی حرارت ملایم بگذارید تا بجوشد و کف کند.</li><li>گام ۴: پس از جوشیدن، ۱ دقیقه صبر کنید، سپس صاف کنید و با خرما سرو کنید.</li></ul>","kind":"item"},{"id":214,"title":"قهوه با شن و ماسه (Saudi Arabian Sand Coffee)","body":"<ul><li>در صحرا‌های عربستان، قهوه را در یک قهوه‌جوش مسی با شن داغ می‌جوشانند.</li><li>ظرف را در میان شن‌های داغ بیابان قرار می‌دهند و حرارت یکنواخت آن باعث عصاره‌گیری ملایم و طعمی دودی و خاکی می‌شود.</li></ul>","kind":"item"},{"id":611,"title":"کافه زولو (Café Zulu)","body":"<p>قهوه اسپرسو با اضافه‌کردن یک لایه خامه ترش (sour cream) و فلفل سیاه – نوشیدنی سنتی آفریقای جنوبی.</p>","kind":"item"},{"id":612,"title":"کافه دی اولا (Café de Olla)","body":"<p>قهوه مکزیکی با پیلونسیلو (شکر نیشکر)، دارچین، میخک و پوست پرتقال که در قوری سفالی دم می‌شود.</p>","kind":"item"},{"id":613,"title":"قهوه سوبیا (Coffee Sobia)","body":"<p>برخلاف برداشت رایج، «سوبیا» ریشه در تایلند ندارد؛ سوبیا (سوبیه) نوشیدنی سنتی منطقه‌ی حجاز در عربستان سعودی (و مصر) است که به‌ویژه در ماه رمضان نوشیده می‌شود و اصولاً از نان تست‌شده یا جو، همراه با شکر و هل تهیه می‌شود. «قهوه‌سوبیا» بازخوانی مدرن کافه‌های سعودی از همین نوشیدنی است که به آن اسپرسو یا قهوه‌ی سرد اضافه می‌شود.</p><ul><li>گام ۱ (پایه‌ی سوبیا): ۲ برش نان تست‌شده یا کمی جو پخته را با آب گرم، شکر، هل و کمی وانیل مخلوط و صاف کنید تا مایعی شیری‌رنگ و شیرین به دست آید (یا از سوبیای آماده‌ی بسته‌بندی استفاده کنید).</li><li>گام ۲ (سرد کردن): مایع صاف‌شده را حداقل ۲ ساعت در یخچال خنک کنید.</li><li>گام ۳ (ترکیب با قهوه): یک شات اسپرسو یا ۶۰ میلی‌لیتر قهوه‌ی دم‌آوری‌شده‌ی سرد را روی یخ در لیوان بریزید.</li><li>گام ۴ (سرو): سوبیای سرد را به آرامی روی قهوه اضافه کنید تا دو لایه شکل بگیرد؛ در صورت تمایل با کمی دارچین تزیین کنید.</li></ul>","kind":"item"},{"id":614,"title":"باک‌افی (Buckafé)","body":"<p>قهوه فیلتری + کره بادام‌زمینی + پودر کاکائو – نوشیدنی پرانرژی سالم‌تر از بولت‌پروف.</p>","kind":"item"},{"id":615,"title":"کافه کان لچه (Café con Leche)","body":"<p>اسپرسو (یا قهوه فوری) با شیر جوشیده شده به‌نسبت ۱:۱ – اسپانیا و آمریکای لاتین (مشابه کافه آوله اما با شیر آب‌شده نه بخارزده).</p>","kind":"item"},{"id":616,"title":"مازاگران (Mazagran)","body":"<p>مازاگران قدیمی‌ترین قهوه‌ی سرد شناخته‌شده در جهان است؛ در دهه‌ی ۱۸۴۰ میلادی، سربازان فرانسوی مستقر در قلعه‌ی «مازاگران» در الجزایر، برای مقابله با گرمای بیابان، قهوه‌ی شیرین را با آب سرد رقیق می‌کردند. بعدها در پرتغال با افزودن آب‌لیمو به شکل امروزی‌اش رسید و در اتریش و فرانسه نیز با کمی رام سرو می‌شود.</p><ul><li>گام ۱ (دم‌آوری): یک شات اسپرسو یا ۴۰-۵۰ میلی‌لیتر قهوه‌ی غلیظ دم کنید و اجازه دهید کمی خنک شود.</li><li>گام ۲ (شیرین‌کردن): درحالی‌که هنوز گرم است، ۱ تا ۲ قاشق‌چای‌خوری شکر را در آن حل کنید.</li><li>گام ۳ (سرو سنتی پرتغالی): لیوان بلند را پر از یخ کنید، قهوه‌ی شیرین‌شده را روی یخ بریزید و آب‌لیمو تازه (حدود نیم لیمو) اضافه کنید؛ به دلخواه کمی رام نیز می‌ریزند.</li><li>گام ۴ (سرو): هم بزنید و بلافاصله سرو کنید؛ طعم آن ترکیبی تازه از تلخی قهوه و ترشی لیمو است.</li></ul><div class=\"note-box\"><strong>نکته</strong>گاهی مازاگران را «نخستین قهوه‌ی سرد مدرن جهان» می‌نامند.</div>","kind":"item"},{"id":617,"title":"فارمرز (Farmer’s Coffee)","body":"<p>قهوه فیلتری با یک تخم‌مرغ خام که داخل فیلتر ریخته می‌شود تا تفاله‌ها را بگیرد – روش قدیمی اسکاندیناوی.</p>","kind":"item"},{"id":618,"title":"قهوه آتشی (Flaming Coffee)","body":"<p>قهوه‌ی آتشین برگرفته از سنت اسپانیایی-گالیسیایی «کیمادا» (Queimada) و «کاراخیو» (Carajillo) است: مشروب الکلی با درجه‌ی الکل بالا روی قهوه (یا کنارش) شعله‌ور می‌شود تا هم الکل تندش تعدیل شود و هم نمایشی دیدنی هنگام سرو داشته باشد.</p><ul><li>گام ۱ (احتیاط ایمنی): این روش شامل آتش باز است؛ تنها با ظرف نسوز، دور از مواد قابل‌اشتعال و با احتیاط کامل انجام شود.</li><li>گام ۲ (دم‌آوری): یک فنجان قهوه‌ی غلیظ (اسپرسو یا دم‌آوری سنتی) آماده کنید.</li><li>گام ۳ (مشروب): مقدار کمی مشروب با درصد الکل بالا (مانند رام یا براندی) را در یک قاشق فلزی یا لیوان کوچک نسوز بریزید.</li><li>گام ۴ (شعله‌ور کردن): با احتیاط مشروب را شعله‌ور کرده و اجازه دهید چند ثانیه بسوزد تا الکل تندش کاهش یابد، سپس آن را داخل قهوه خاموش/اضافه کنید.</li><li>گام ۵ (سرو): با کمی پوست پرتقال یا چند دانه قهوه‌ی رست‌شده تزیین و بلافاصله سرو کنید.</li></ul>","kind":"item"},{"id":619,"title":"سه‌دری (Three-in-One)","body":"<p>«سه‌دری» به پرمصرف‌ترین شکل قهوه‌ی فوری در آسیا (به‌ویژه مالزی، ویتنام و چین) گفته می‌شود: بسته‌های تک‌نفره‌ای که هر سه‌ی «قهوه‌ی فوری + کرمر (شیرخشک صنعتی) + شکر» را از پیش ترکیب کرده‌اند.</p><ul><li>گام ۱: محتوای یک پاکت سه‌دری را داخل لیوان بریزید.</li><li>گام ۲: حدود ۱۵۰-۱۸۰ میلی‌لیتر آب داغ (نه لزوماً در حال جوش) روی آن اضافه کنید.</li><li>گام ۳: کاملاً هم بزنید تا پودر کرمر و شکر به‌طور یکنواخت حل شود.</li><li>گام ۴ (نسخه‌ی سرد): می‌توان همان مخلوط را روی یخ ریخت تا نسخه‌ای سریع از قهوه‌ی سرد شیرین به‌دست آید.</li></ul><div class=\"note-box\"><strong>نکته</strong>کیفیت طعم آن معمولاً پایین‌تر از قهوه‌ی دم‌آوری‌شده‌ی تازه است، اما سرعت و در دسترس‌بودنش رازِ محبوبیت جهانی‌اش است.</div>","kind":"item"}],"hero":"assets/images/traditional.svg"},{"id":"modern","icon":"future","title":"مدرن، عملکردی و عجیب","items":[{"id":112,"title":"دالگونا (Dalgona Coffee – قهوه کف‌دار کره‌ای)","body":"<ul><li>گام ۱ (آماده‌سازی کف): در یک کاسه متوسط، ۲ قاشق غذاخوری (۲۰ گرم) قهوه فوری، ۲ قاشق غذاخوری (۲۰ گرم) شکر سفید، و ۲ قاشق غذاخوری (۳۰ میلی‌لیتر) آب بسیار داغ (نه جوش، حدود ۸۰ درجه) بریزید.</li><li>گام ۲ (هم‌زدن): با همزن برقی (دستی یا ایستاده) به‌مدت ۲ تا ۳ دقیقه با سرعت بالا هم بزنید تا مخلوط به کفی غلیظ، براق، کش‌دار و به‌رنگ کاراملی روشن تبدیل شود (حجم آن ۳ تا ۴ برابر می‌شود). وقتی همزن را بلند کنید، قله‌های سفت و ایستاده تشکیل می‌شود.</li><li>گام ۳ (آماده‌سازی لیوان): یک لیوان بلند را تا ۲/۳ از شیر سرد (ترجیحاً شیر کامل یا شیر گیاهی) پر کنید. در صورت تمایل، یخ اضافه کنید.</li><li>گام ۴ (ترکیب نهایی): کف قهوه را به‌آرامی روی شیر بریزید (لایه‌بندی). با قاشق کف را پهن کنید تا سطح یکدست شود.</li><li>گام ۵ (سرو): بدون هم زدن سرو کنید. مهمان خود کف را با شیر مخلوط می‌کند. طعمی شیرین، کرم‌دار و با بافتی سبک و ابری.</li></ul>","kind":"item"},{"id":113,"title":"قهوه ضدگلوله (Bulletproof Coffee)","body":"<ul><li>گام ۱ (دم‌آوری قهوه فیلتری): ۲۵۰ میلی‌لیتر قهوه فیلتری باکیفیت (ترجیحاً با برشته‌کاری متوسط و آسیاب متوسط، مانند V60 یا فرنچ‌پرس) دم کنید. از قهوه‌هایی با اسیدیته پایین استفاده کنید (مانند برزیلی یا سوماترایی).</li><li>گام ۲ (آماده‌سازی مواد چرب): ۱ تا ۲ قاشق غذاخوری (۱۵–۳۰ میلی‌لیتر) روغن MCT (تری‌گلیسیرید‌های زنجیره‌متوسط) و ۱ تا ۲ قاشق غذاخوری کره حیوانی بدون نمک (ترجیحاً از گاو‌های تغذیه‌شده با علف – grass-fed) را در مخلوط‌کن بریزید.</li><li>گام ۳ (مخلوط‌کردن): قهوه داغ را به مخلوط‌کن اضافه کنید و به‌مدت ۲۰–۳۰ ثانیه با سرعت بالا مخلوط کنید تا کاملاً امولسیون شده و بافتی کرم‌مانند و شیری شکل (بدون لایه روغن) ایجاد شود.</li><li>گام ۴ (سرو): بلافاصله در لیوان بریزید و بنوشید. این نوشیدنی برای رژیم کتوژنیک (بدون کربوهیدرات، پرچرب) طراحی شده و انرژی طولانی‌مدت و هوشیاری ذهنی ایجاد می‌کند (بدون افت قند خون).</li></ul>","kind":"item"},{"id":114,"title":"ردآی (Red Eye – قهوه با یک شات اسپرسو اضافه)","body":"<ul><li>گام ۱ (دم‌آوری قهوه فیلتری): یک فنجان بزرگ (۳۰۰ میلی‌لیتری) قهوه فیلتری (فرنچ‌پرس، V60 یا قطره‌ای) به حجم ۲۵۰ میلی‌لیتر دم کنید. (قهوه باید داغ و تازه باشد).</li><li>گام ۲ (افزودن اسپرسو): یک شات اسپرسوی ۳۶ گرمی را مستقیماً روی قهوه فیلتری بریزید (نیازی به هم زدن نیست، خود به خود ترکیب می‌شود).</li><li>گام ۳ (سرو): در صورت تمایل، شکر یا شیر اضافه کنید. میزان کافئین: حدود ۲۰۰–۲۵۰ میلی‌گرم. نوشیدنی بسیار قوی برای بیداری فوری.</li></ul>","kind":"item"},{"id":115,"title":"بلک‌آی (Black Eye – قهوه با دو شات اسپرسو)","body":"<ul><li>گام ۱ (دم‌آوری قهوه فیلتری): یک فنجان بزرگ (۳۰۰ میلی‌لیتری) قهوه فیلتری به حجم ۲۵۰ میلی‌لیتر دم کنید.</li><li>گام ۲ (افزودن دو شات اسپرسو): دو شات اسپرسو (۷۲ گرم) را روی قهوه فیلتری بریزید.</li><li>گام ۳ (سرو): با قاشق هم بزنید و سرو کنید. کافئین: حدود ۳۰۰–۳۵۰ میلی‌گرم – مناسب برای شب‌کاری یا رانندگی طولانی.</li></ul>","kind":"item"},{"id":116,"title":"ددآی (Dead Eye – قهوه با سه شات اسپرسو)","body":"<ul><li>گام ۱ (دم‌آوری قهوه فیلتری): یک فنجان بزرگ (۳۵۰ میلی‌لیتری) قهوه فیلتری به حجم ۲۵۰ میلی‌لیتر دم کنید.</li><li>گام ۲ (افزودن سه شات اسپرسو): سه شات اسپرسو (۱۰۸ گرم – حدود ۱۰۰ میلی‌لیتر) را روی قهوه فیلتری بریزید.</li><li>گام ۳ (سرو): هم بزنید و بلافاصله سرو کنید. کافئین: حدود ۴۵۰–۵۰۰ میلی‌گرم (حداکثر دوز ایمن روزانه برای بزرگسالان – مصرف این نوشیدنی در یک نوبت بسیار قوی است و تنها برای افرادی با تحمل بالا توصیه می‌شود).</li></ul>","kind":"item"},{"id":117,"title":"قهوه فوری ساده (Instant Black)","body":"<ul><li>گام ۱ (انتخاب قهوه فوری): ۲ قاشق چای‌خوری (۵–۶ گرم) قهوه فوری (به‌صورت پودر یا گرانول) را در فنجان بریزید.</li><li>گام ۲ (ریختن آب داغ): ۲۰۰ میلی‌لیتر آب با دمای ۸۵–۹۰ درجه سانتی‌گراد را روی آن بریزید (آب جوش باعث سوختن و تلخی بیش‌ازحد می‌شود).</li><li>گام ۳ (هم‌زدن): با قاشق به‌مدت ۵–۱۰ ثانیه هم بزنید تا کاملاً حل شود.</li><li>گام ۴ (سرو): در صورت تمایل، شکر یا شیر اضافه کنید. ساده‌ترین و سریع‌ترین مدل قهوه.</li></ul>","kind":"item"},{"id":118,"title":"کنسانتره مایع (Liquid Coffee Concentrate – قهوه مایع غلیظ برای مصارف خانگی)","body":"<ul><li>گام ۱ (دم‌آوری اولیه): ۱۰۰ گرم قهوه آسیاب‌شده (درجه متوسط-ریز، حدود ۴۰۰–۵۰۰ میکرون) را در یک ظرف بزرگ بریزید.</li><li>گام ۲ (ریختن آب سرد): ۵۰۰ میلی‌لیتر آب سرد (دمای اتاق) را به آن اضافه کنید (نسبت ۱:۵). هم بزنید تا همه ذرات خیس شوند.</li><li>گام ۳ (خیساندن): ظرف را دربسته به‌مدت ۱۲ ساعت در یخچال قرار دهید (مشابه کلد برو اما با نسبت کمتر).</li><li>گام ۴ (صاف‌کردن): قهوه را از فیلتر پارچه‌ای یا کاغذی عبور دهید تا تفاله‌ها جدا شوند (حداقل دو بار).</li><li>گام ۵ (نگهداری): کنسانتره را در بطری شیشه‌ای در یخچال نگهداری کنید (تا ۳ هفته).</li><li>گام ۶ (سرو): برای هر فنجان، ۳۰–۵۰ میلی‌لیتر کنسانتره را با آب داغ یا سرد (تا ۲۰۰ میلی‌لیتر) رقیق کنید. برای شیر، ۳۰ میلی‌لیتر کنسانتره + ۱۵۰ میلی‌لیتر شیر سرد/گرم. طعمی غلیظ و همه‌کاره، مناسب برای دم‌آوری سریع در هر روش.</li></ul>","kind":"item"}],"hero":"assets/images/modern.svg"},{"id":"unusual","icon":"unusual","title":"شگفت‌انگیز و غیرمعمول","items":[{"id":620,"title":"قهوه با پوست تخم‌مرغ (Egg Shell Coffee)","body":"<p>برای کاهش اسیدیته و تلخی – پودر قهوه با پوست تخممرغ کوبیده (در روش ترک یا جذوه) دم میشود.</p>","kind":"item"},{"id":621,"title":"قهوه با نمک دریا (Sea Salt Coffee)","body":"<p>یک پیمانه نمک دریا به قهوه فیلتری اضافه میشود – برجستهسازی شیرینی و کاهش تلخی (ترکیه و ایران).</p>","kind":"item"},{"id":622,"title":"قهوه با کره و عسل (Honey Butter Coffee)","body":"<p>نسخه‌ای شیرین‌تر و ملایم‌تر از «قهوه‌ی گلوله‌ضدگلوله» (Bulletproof Coffee): به‌جای روغن نارگیل خالص، از کره و عسل استفاده می‌شود تا طعمی شبیه کارامل ایجاد شود.</p><ul><li>گام ۱ (دم‌آوری): یک فنجان قهوه‌ی داغ و تازه (حدود ۲۴۰ میلی‌لیتر) دم کنید.</li><li>گام ۲ (افزودن مواد): ۱ قاشق‌غذاخوری کره‌ی بدون‌نمک و ۱ قاشق‌چای‌خوری عسل را به قهوه‌ی داغ اضافه کنید.</li><li>گام ۳ (امولسیون): با همزن دستی یا فرندر ۱۵-۲۰ ثانیه هم بزنید تا کره کاملاً حل و بافت نوشیدنی کرمی و کف‌دار شود.</li><li>گام ۴ (سرو): بلافاصله در فنجان گرم سرو کنید.</li></ul><div class=\"note-box\"><strong>نکته</strong>طرفداران این نوشیدنی معتقدند چربی موجود، جذب کافئین را کندتر و انرژی را پایدارتر می‌کند؛ شواهد علمی قطعی در این باره محدود است.</div>","kind":"item"},{"id":623,"title":"قهوه با ریشه‌ی شیرین‌بیان (Licorice Root Coffee)","body":"<p>افزودن ریشه‌ی شیرین‌بیان به قهوه، سنتی رایج در بخش‌هایی از خاورمیانه و شمال آفریقا (به‌ویژه مصر و برخی مناطق ایران) است؛ شیرین‌بیان طعمی ملایم و کمی شیرین می‌دهد و اسیدیته‌ی قهوه را کاهش می‌دهد.</p><ul><li>گام ۱ (آماده‌سازی): ۱ قاشق‌چای‌خوری پودر ریشه‌ی شیرین‌بیان خشک را با پودر قهوه (نسبت تقریبی ۱ به ۱۰) مخلوط کنید.</li><li>گام ۲ (دم‌آوری): مخلوط را به روش معمول (ترک، فرنچ‌پرس یا فیلتر) دم کنید.</li><li>گام ۳ (سرو): معمولاً بدون شکر سرو می‌شود، چون شیرین‌بیان خودش شیرینی ملایمی به نوشیدنی می‌دهد.</li></ul><div class=\"note-box\"><strong>هشدار سلامتی</strong>مصرف زیاد شیرین‌بیان می‌تواند فشار خون را بالا ببرد؛ افراد مبتلا به فشار خون بالا یا بیماری قلبی باید با احتیاط و در حد کم مصرف کنند.</div>","kind":"item"},{"id":624,"title":"قهوه با پودر ماهی (Fish Coffee)","body":"<p>شوخی تاریخی – در سوئد قرن ۱۹، برخی از ماهی خشک شده برای تصفیه‌ی قهوه‌ی ارزان استفاده میکردند (افسانه).</p>","kind":"item"}],"hero":"assets/images/unusual.svg"},{"id":"rare_beans","icon":"rarebeans","title":"دانه‌های نادر و گران‌قیمت","items":[{"id":625,"title":"قهوه کوپی لواک اندونزیایی (Kopi Luwak)","body":"<p>دانه‌هایی که پس از عبور از دستگاه گوارش «موش خرمای آسیایی» (Asian Palm Civet) و تخمیر آنزیمی طبیعی جمع‌آوری می‌شوند؛ این فرآیند اسیدیته‌ی قهوه را کاهش داده و طعمی ملایم‌تر و کمی خاکی ایجاد می‌کند. کوپی‌لواک اصیل و وحشی (جمع‌آوری‌شده از طبیعت) از گران‌ترین قهوه‌های جهان است (تا حدود ۱۰۰۰ دلار در کیلوگرم).</p><div class=\"note-box\"><strong>نکته‌ی اخلاقی</strong>بخش بزرگی از کوپی‌لواکِ بازار امروز از مزارع پرورش موش خرما در قفس تولید می‌شود که نهادهای حقوق حیوانات (از جمله سازمان‌هایی مثل World Animal Protection) آن را به‌دلیل شرایط نامناسب نگهداری نقد کرده‌اند. خرید کوپی‌لواکِ دارای گواهی «وحشی و ردیابی‌شده» (wild-sourced, traceable) توصیه می‌شود.</div>","kind":"item"},{"id":626,"title":"قهوه ژاکوبرد برزیلی (Jacu Bird Coffee)","body":"<p>دانه‌هایی که پرنده‌ی «ژاکو» (Jacu Bird) در جنگل‌های برزیل می‌خورد و بخشی از آن‌ها بدون هضم کامل دفع می‌شوند؛ برخلاف کوپی‌لواک، این پرنده در طبیعت آزاد و بدون قفس جمع‌آوری می‌شود، به همین دلیل از نظر اخلاقی مقبول‌تر شناخته می‌شود. طعم نهایی ملایم، کم‌تلخی و با کمی شیرینی گزارش شده است.</p>","kind":"item"},{"id":627,"title":"قهوه فیل تایلندی (Elephant Coffee)","body":"<p>مشابه فرآیند کوپی‌لواک اما با فیل‌های آسیایی در تایلند: دانه‌ها پس از عبور از دستگاه گوارش فیل و تخمیر آنزیمی طولانی (حدود ۱۵-۳۰ ساعت) جمع‌آوری می‌شوند. آنزیم‌های گوارشی فیل پروتئین‌های تلخ‌ساز دانه را تجزیه کرده و طعمی بسیار ملایم، کم‌اسید و کمی شبیه به شکلات ایجاد می‌کند.</p>","kind":"item"},{"id":628,"title":"قهوه عاج سیاه تایلندی (Black Ivory Coffee)","body":"<p>گران‌ترین قهوه‌ی تجاری جهان (بیش از ۱۰۰۰-۱۵۰۰ دلار در کیلوگرم)؛ تولیدشده در ساحل عاج (تایلند) با استفاده از همان روش هضم توسط فیل. برند «بلک آیوری» با همکاری پناهگاه فیل‌های تایلند، بخشی از درآمد فروش را صرف نگهداری و درمان فیل‌ها می‌کند که آن را از نظر رفاه حیوانات نمونه‌ی نسبتاً مثبت‌تری در میان قهوه‌های «فرآوری‌شده با حیوانات» می‌سازد.</p><div class=\"note-box\"><strong>نکته</strong>با این‌حال، کارشناسان توصیه می‌کنند پیش از خرید هر قهوه‌ی مرتبط با حیوانات (کوپی‌لواک، بلک‌آیوری، ژاکوبرد)، گواهی منشأ و شرایط نگهداری حیوانات را بررسی کنید.</div>","kind":"item"}],"hero":"assets/images/rare_beans.svg"}];
